export const PANEL_CSS = "/* UAI 看板 · 设计令牌与样式（唯一源）\n * 生成物：packages/uai-dsh-bundle/lib/panel-css.js（scripts/build-css.mjs 生成，勿手改生成物）\n * 令牌依据：docs/design/ui-20261118-panel/verify/contrast.mjs 的实测比值（12/12 达标）\n * 概念：控制室仪表排 —— 先看数，再看灯，最后才看字。无卡片墙、无圆角、无发光边框。\n */\n\n:root,\n.uai-panel {\n  /* 表面（三级：页 / 面板 / 抬升） */\n  --uai-bg1: #020617;\n  --uai-bg2: #0E1223;\n  --uai-bg3: #1A1E2F;\n\n  /* 文字（fg3 已由 #5C6B85 提到 #7C8AA6：原值只有 3.6:1，不够 AA） */\n  --uai-fg1: #F8FAFC;   /* 17.77:1 on bg2 */\n  --uai-fg2: #94A3B8;   /* 7.25:1  on bg2 */\n  --uai-fg3: #7C8AA6;   /* 5.35:1  on bg2 */\n\n  /* 线：装饰线只做分隔（1.80:1），控件边框必须过 3:1 */\n  --uai-line: #334155;    /* 1.80:1 装饰 */\n  --uai-line-2: #556784;  /* 3.24:1 控件边框 */\n\n  /* 状态（都由实测修正过：#DC2626→#F04438、#F59E0B→#F5A524、#22C55E→#3DDC84） */\n  --uai-green: #3DDC84;   /* 10.42:1 */\n  --uai-amber: #F5A524;   /* 9.11:1  */\n  --uai-red: #F04438;     /* 4.95:1  */\n  --uai-accent: #16A34A;\n  --uai-accent-ink: #04140A;\n\n  /* 排版：UI 密排 1.45，数字一律等宽 + tabular */\n  --uai-font: system-ui, -apple-system, \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  --uai-mono: ui-monospace, SFMono-Regular, \"JetBrains Mono\", Consolas, monospace;\n  --uai-fs-micro: 11px;\n  --uai-fs-sm: 12px;\n  --uai-fs-base: 13px;\n  --uai-fs-lead: 16px;\n  --uai-fs-title: 19px;\n\n  /* 间距 8pt 网格 */\n  --uai-s1: 4px;\n  --uai-s2: 8px;\n  --uai-s3: 12px;\n  --uai-s4: 16px;\n  --uai-s5: 24px;\n  --uai-row: 36px;\n\n  /* 运动：低预算档 —— 只有状态切换与焦点反馈，无入场、无视差 */\n  --uai-dur: 160ms;\n  --uai-ease: cubic-bezier(0.22, 0.61, 0.36, 1);\n}\n\n.uai-panel,\n.uai-panel * { box-sizing: border-box; }\n\n.uai-panel {\n  background: var(--uai-bg1);\n  color: var(--uai-fg1);\n  font-family: var(--uai-font);\n  font-size: var(--uai-fs-base);\n  line-height: 1.45;\n  min-height: 100%;\n  font-variant-numeric: tabular-nums;\n}\n\n/* ── 顶栏：标题 + 计数徽标 + 两个动作 ───────────────────────────── */\n.uai-head {\n  display: flex; align-items: center; gap: 10px;\n  height: 52px; padding: 0 var(--uai-s3);\n  background: var(--uai-bg2);\n  border-bottom: 1px solid var(--uai-line);\n}\n.uai-title { font-size: var(--uai-fs-title); font-weight: 600; letter-spacing: -0.01em; }\n.uai-badge {\n  font-family: var(--uai-mono); font-size: var(--uai-fs-micro);\n  letter-spacing: 0.08em; color: var(--uai-fg2);\n  border: 1px solid var(--uai-line); padding: 2px 6px;\n}\n.uai-actions { margin-left: auto; display: flex; gap: var(--uai-s2); }\n\n.uai-btn {\n  height: 30px; padding: 0 var(--uai-s3);\n  border: 1px solid var(--uai-line-2); background: transparent; color: var(--uai-fg1);\n  font: inherit; font-size: var(--uai-fs-base); cursor: pointer;\n  transition: background var(--uai-dur) var(--uai-ease),\n              border-color var(--uai-dur) var(--uai-ease),\n              transform var(--uai-dur) var(--uai-ease);\n}\n.uai-btn:hover:not(:disabled) { background: var(--uai-bg3); border-color: var(--uai-fg3); }\n.uai-btn:active:not(:disabled) { transform: translateY(1px); }\n.uai-btn:disabled { opacity: 0.55; cursor: default; }\n.uai-btn--primary { background: var(--uai-bg3); border-color: var(--uai-line-2); color: var(--uai-fg1); font-weight: 600; }\n.uai-btn--primary:hover:not(:disabled) { background: #232841; border-color: var(--uai-fg3); }\n\n/* 焦点：键盘可见，不靠颜色单独传达 */\n.uai-panel :focus-visible {\n  outline: 2px solid var(--uai-green);\n  outline-offset: 2px;\n}\n\n/* ── Bento 仪表块 ────────────────────────────────────────────── */\n.uai-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 1px;                     /* 用 1px gap + 底色造分隔线，避免额外边框 */\n  background: var(--uai-line);\n  border-bottom: 1px solid var(--uai-line);\n}\n.uai-cell {\n  background: var(--uai-bg2);\n  padding: var(--uai-s3);\n  display: flex; flex-direction: column; gap: var(--uai-s1);\n  min-width: 0;\n}\n.uai-cell__k {\n  font-size: var(--uai-fs-micro); letter-spacing: 0.14em; text-transform: uppercase;\n  color: var(--uai-fg2);\n}\n.uai-cell__v {\n  font-family: var(--uai-mono); font-size: 22px; line-height: 1.1;\n  display: flex; align-items: baseline; gap: var(--uai-s2);\n}\n.uai-cell__u { font-size: var(--uai-fs-sm); color: var(--uai-fg3); font-family: var(--uai-font); }\n.uai-cell__note { font-size: var(--uai-fs-sm); color: var(--uai-fg3); }\n\n/* ── 表：席位一行为一席，36px 密排 ──────────────────────────── */\n.uai-section { border-bottom: 1px solid var(--uai-line); }\n.uai-section__h {\n  display: flex; align-items: center; justify-content: space-between;\n  height: 30px; padding: 0 var(--uai-s3);\n  background: var(--uai-bg2);\n  font-size: var(--uai-fs-micro); letter-spacing: 0.14em; text-transform: uppercase;\n  color: var(--uai-fg2);\n}\n.uai-section__h span:last-child { font-family: var(--uai-mono); letter-spacing: 0; }\n\n.uai-row {\n  display: grid;\n  /* 四列：名字 / 状态 / 锁来源 / pid（pid 贴右端，锁源紧跟状态，避免串成一句话） */\n  grid-template-columns: minmax(0, 200px) 88px minmax(0, 132px) minmax(0, 1fr);\n  align-items: center; gap: var(--uai-s3);\n  height: var(--uai-row); padding: 0 var(--uai-s3);\n  border-top: 1px solid var(--uai-line);\n  transition: background var(--uai-dur) var(--uai-ease);\n}\n.uai-row:hover { background: var(--uai-bg3); }\n.uai-row__name { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.uai-row__state { display: inline-flex; align-items: center; gap: 6px; font-size: var(--uai-fs-sm); color: var(--uai-fg2); }\n.uai-row__meta { font-family: var(--uai-mono); font-size: var(--uai-fs-sm); color: var(--uai-fg3); text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.uai-row__src { font-family: var(--uai-mono); font-size: var(--uai-fs-micro); color: var(--uai-fg3); letter-spacing: 0.04em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n\n/* 状态灯：形状 + 颜色双编码（不只靠颜色） */\n.uai-dot { width: 6px; height: 6px; border-radius: 50%; flex: 0 0 auto; background: var(--uai-fg3); }\n.uai-dot--on { background: var(--uai-green); }\n.uai-dot--warn { background: var(--uai-amber); }\n.uai-dot--off { background: var(--uai-red); }\n\n/* ── 检测结果：标签 + 状态 + 路径 ───────────────────────────── */\n.uai-section--alt { background: var(--uai-bg2); }\n.uai-section--alt .uai-section__h { background: transparent; border-bottom: 1px solid var(--uai-line); }\n.uai-cap { display: flex; flex-wrap: wrap; gap: var(--uai-s1); padding: var(--uai-s3); background: var(--uai-bg3); }\n.uai-tag {\n  font-family: var(--uai-mono); font-size: var(--uai-fs-micro); letter-spacing: 0.06em;\n  border: 1px solid var(--uai-line); color: var(--uai-fg2);\n  padding: 2px 6px; text-transform: uppercase;\n}\n.uai-tag--ready { border-color: rgba(61, 220, 132, 0.45); color: var(--uai-green); }\n\n.uai-empty { padding: var(--uai-s3); color: var(--uai-fg2); font-size: var(--uai-fs-sm); }\n.uai-error {\n  margin: var(--uai-s3); padding: var(--uai-s3);\n  border: 1px solid var(--uai-red); color: var(--uai-red); font-size: var(--uai-fs-sm);\n}\n\n/* ── 390px：单列，行内改成两行 ──────────────────────────────── */\n@media (max-width: 560px) {\n  .uai-grid { grid-template-columns: minmax(0, 1fr); }\n  .uai-row { grid-template-columns: minmax(0, 1fr) auto; height: auto; padding: 8px var(--uai-s3); row-gap: 2px; }\n  .uai-row__src { grid-column: 1 / -1; grid-row: 2; }\n  .uai-row__meta { grid-column: 1 / -1; grid-row: 3; text-align: left; }\n  .uai-head { height: auto; padding: 8px var(--uai-s3); flex-wrap: wrap; }\n  .uai-actions { margin-left: 0; width: 100%; }\n  .uai-btn { flex: 1 1 auto; }\n}\n\n/* ── 低运动预算的降级：用户要求减少动效时全部瞬切 ───────────── */\n@media (prefers-reduced-motion: reduce) {\n  .uai-panel, .uai-panel * {\n    transition-duration: 0ms !important;\n    animation-duration: 0ms !important;\n  }\n}\n";
